docker exec startuphafen-devcontainer-maildev-1 node -e "
const net = require('net');
const s = net.connect(1025, '127.0.0.1', () => {});
let buf = '';
s.on('data', d => {
  buf += d.toString();
  if (buf.startsWith('220')) s.write('EHLO test\r\n');
  else if (buf.includes('250-') || buf.includes('250 EHLO') || buf.includes('EHLO')) {
    if (buf.includes('EHLO') && !buf.includes('DATA')) s.write('QUIT\r\n');
    else s.end();
  }
});
s.on('end', () => { console.log(buf); process.exit(0); });
setTimeout(() => { console.log(buf || 'NO RESPONSE'); process.exit(1); }, 4000);
"

